-- jp-go N4 vocabulary: certain meaning / usage corrections found during full lesson review.
-- Deterministic + idempotent: values are replaced with reviewed canonical text, not appended.
-- Homographs are restricted by reading when needed.

with fixes(word_jp, reading_furigana, meaning_vi, usage_note_vi) as (
values
('家具', null, 'đồ nội thất', '家具 = đồ nội thất nói chung; không chỉ đồ gỗ. Ví dụ: 家具を買う／家具を置く。'),
('通信販売', null, 'bán hàng từ xa; mua hàng qua đặt hàng/online', '通信販売 là hình thức bán hàng không cần đến cửa hàng trực tiếp (mail-order, điện thoại, internet...); không giới hạn ở mua qua mạng.'),
('開く', 'ひらく', 'mở; tổ chức; mở ra', '開く（ひらく）: mở vật/sự kiện hoặc tổ chức: 本を開く、会議を開く、店を開く. Phân biệt 開く（あく） là tự động từ: cửa/cửa sổ mở.'),
('開く', 'あく', 'mở ra (tự động từ)', '開く（あく）: ドアが開く／窓が開く. Phân biệt 開く（ひらく）: 本を開く／会議を開く.'),
('付き合う', null, 'giao thiệp; đi cùng; hẹn hò', '人と付き合う có thể là giao thiệp/quan hệ, hẹn hò; 買い物に付き合う = đi cùng ai làm việc gì. Không chỉ có nghĩa hẹn hò.'),
('通う', null, 'đi đều đặn; đi học/đi làm/đi khám thường xuyên', '学校に通う、会社に通う、病院に通う. Nhấn mạnh việc đi lại thường xuyên đến một nơi.'),
('美容院', null, 'tiệm làm tóc; salon làm đẹp', '美容院 thường chỉ salon tóc/làm đẹp, đặc biệt cắt/uốn/nhuộm tóc.'),
('偉い', null, 'đáng nể; giỏi; có địa vị cao', '偉い人 = người có địa vị/đáng kính; よく頑張って偉い = giỏi, đáng khen. Không đơn giản chỉ là “siêu”.'),
('戻す', null, 'đưa/trả về chỗ hoặc trạng thái cũ', '本を元の場所に戻す、設定を元に戻す. Đây là tha động từ; 戻る là tự động từ.'),
('うれしい', null, 'vui; mừng', 'Cảm xúc của người nói khi có điều tốt xảy ra: 合格できてうれしい. Không phải tính cách “vui vẻ”.'),
('先生', null, 'thầy/cô; bác sĩ; cách gọi người có chuyên môn/vị thế được kính trọng', '先生 không chỉ là bác sĩ. Tùy ngữ cảnh có thể là giáo viên, bác sĩ, luật sư, chính trị gia, nghệ sĩ...'),
('出る', null, 'ra; xuất hiện; tham gia; rời khỏi; được đưa ra', 'Động từ đa nghĩa: 家を出る、試合に出る、テレビに出る、結果が出る. Học cùng trợ từ/ngữ cảnh.'),
('失敗する', null, 'thất bại; làm không thành công; mắc lỗi', '試験に失敗する có thể hiểu không thành công nhưng “thi trượt” thường nói 試験に落ちる. 失敗する dùng rộng hơn.'),
('牡牛座', null, 'cung Kim Ngưu (Taurus)', '十二星座の一つ. Không phải “sao Kim Ngưu”.'),
('ことわざ', null, 'tục ngữ', 'ことわざ = proverb/câu nói dân gian cố định. “Thành ngữ” nói chung rộng hơn.'),
('設備', null, 'thiết bị; cơ sở vật chất; hệ thống trang bị', '設備 có thể chỉ hệ thống/cơ sở trang bị nói chung: 生産設備、設備を点検する. Không nhất thiết là một thiết bị đơn lẻ.'),
('仲良くする', null, 'thân thiện; hòa thuận; chơi/quan hệ tốt với nhau', '人と仲良くする = cư xử thân thiện/hòa thuận. Không mang nghĩa riêng “có bạn gái”.'),
('育てる', null, 'nuôi; trồng; đào tạo/phát triển', '子供を育てる、植物を育てる、人材を育てる. Dữ liệu cũ “mắng” là sai nghĩa.'),
('頼む', null, 'nhờ; yêu cầu; đặt', '人に仕事を頼む、料理を頼む. Không có nghĩa “chăm sóc/nuôi dưỡng”.'),
('気持ちが悪い', null, 'khó chịu; buồn nôn; cảm thấy không khỏe', 'Thường diễn tả khó chịu về thể chất hoặc cảm giác ghê/khó chịu. 気分が悪い cũng dùng cho thể trạng; không nên dịch đơn giản là “tâm trạng không tốt”.'),
('西洋化する', null, 'Tây phương hóa', '西洋 = phương Tây nói chung; “Tây Âu hóa” quá hẹp.'),
('インフルエンザ', null, 'cúm; influenza', 'Tên bệnh influenza. “Dịch cúm” chỉ đúng khi ngữ cảnh nói về đợt dịch.'),
('年寄り', null, 'người già; người cao tuổi', '年寄り có thể nghe thẳng/không lịch sự. Trong hướng dẫn hoặc công việc thường ưu tiên お年寄り hoặc 高齢者.'),
('以上', null, 'từ ... trở lên; ít nhất ...', 'Bao gồm chính mốc được nêu: 18歳以上 = từ 18 tuổi trở lên, gồm 18.'),
('以下', null, 'từ ... trở xuống; không quá ...', 'Bao gồm chính mốc được nêu: 12歳以下 = 12 tuổi trở xuống, gồm 12.'),
('オートバイ', null, 'xe máy; mô tô', 'オートバイ = motorcycle nói chung; không nhất thiết chỉ xe phân khối lớn.'),
('発表会', null, 'buổi trình diễn; buổi giới thiệu/trình bày thành quả', 'Dùng cho piano recital, buổi trình bày học tập, giới thiệu sản phẩm... Không chỉ là “buổi phát biểu”.'),
('犯人', null, 'thủ phạm; người gây ra vụ việc/phạm tội cụ thể', '犯人 thường là người bị xác định/tìm kiếm trong một vụ cụ thể. “Tội phạm” nói chung có thể là 犯罪者.'),
('キロ', null, 'kilo; ki-lô-mét hoặc ki-lô-gam tùy ngữ cảnh', '駅まで5キロ = 5 km; 荷物は10キロ = 10 kg. Phải dựa vào danh từ/ngữ cảnh.'),
('会場', null, 'địa điểm tổ chức; hội trường/khu vực sự kiện', 'イベント会場、試験会場. Không giới hạn ở một “hội trường” trong nhà.'),
('洋服', null, 'quần áo kiểu Tây; quần áo thường', 'Đối lập với 和服. Trong tiếng Nhật hiện đại 洋服 cũng thường được dùng đơn giản là quần áo.'),
('成績', null, 'thành tích; kết quả; điểm số', '学校の成績、営業成績. Không chỉ điểm học tập.'),
('冷房', null, 'làm mát; điều hòa làm mát; hệ thống/chế độ làm mát', '冷房を入れる、冷房温度. Không nhất thiết chỉ một “máy lạnh”.'),
('暖房', null, 'sưởi; hệ thống/chế độ sưởi', '暖房を入れる、暖房温度. Không nhất thiết chỉ một “máy sưởi”.'),
('丈夫', null, 'bền; chắc; khỏe mạnh', '丈夫な箱 = thùng bền; 体が丈夫 = cơ thể khỏe. Không chỉ “chắc chắn”.'),
('チキンラーメン', null, 'Chicken Ramen (tên sản phẩm mì ăn liền)', 'Đây là tên sản phẩm/nhãn hàng cụ thể trong ngữ cảnh nguồn; không nên dịch thành danh từ chung “mì gà”.'),
('論文', null, 'bài nghiên cứu học thuật; luận văn/luận án tùy ngữ cảnh', '論文 là academic paper nói chung; 卒業論文, 修士論文... mới xác định loại luận văn cụ thể.'),
('アパート', null, 'căn hộ/nhà chung cư kiểu apartment (thường nhà thuê thấp tầng ở Nhật)', 'Trong cách dùng Nhật, アパート thường khác マンション về kiểu công trình/marketing; không nên gộp mọi chung cư.'),
('ミキサー', null, 'máy xay; máy trộn/mixer tùy ngữ cảnh', 'Trong bếp Nhật, ミキサー thường chỉ blender. Trong kỹ thuật có thể là mixer/máy trộn.'),
('ローン', null, 'khoản vay; vay trả góp/tín dụng', '住宅ローン、自動車ローン、ローンを組む. Không chỉ vay ngân hàng nói chung.'),
('音楽家', null, 'nhạc sĩ; nghệ sĩ/người hoạt động âm nhạc', '音楽家 rộng hơn “nhà soạn nhạc”; 作曲家 mới là composer.'),
('広める', null, 'phổ biến; lan rộng; quảng bá', '情報を広める、活動を広める. “Tuyên truyền” có sắc thái hẹp hơn và không phải lúc nào phù hợp.'),
('交通', null, 'giao thông; vận tải; sự đi lại', '交通が便利、交通事故、交通状況. “Phương tiện giao thông” thường là 交通手段／乗り物.'),
('関する', null, 'liên quan đến; về', 'Nに関するN = N liên quan đến/về: 安全に関する資料.'),
('翌週', null, 'tuần kế tiếp; tuần sau so với mốc đã nói', '翌週 lấy một thời điểm trong câu làm mốc. 来週 lấy hiện tại làm mốc.'),
('講師', null, 'giảng viên; người hướng dẫn/giảng dạy', '講師 không đồng nghĩa “giáo sư”. 大学講師, 外部講師, セミナー講師.'),
('ボランティア', null, 'tình nguyện; người tình nguyện/tình nguyện viên', 'ボランティア活動、ボランティアを募集する. Không nhất thiết là “nhân viên” theo quan hệ lao động.'),
('番線', null, 'số đường ray/sân ga trong nhà ga', '3番線 = đường/sân ga số 3. Không phải “số tuyến tàu”.'),
('両親', null, 'cha mẹ; cả bố và mẹ', '両親 = cả hai cha mẹ. “Phụ huynh/người giám hộ” nói chung thường là 保護者.'),
('生徒', null, 'học sinh; người học', 'Thường dùng cho học sinh trường/lớp. Sinh viên đại học thường dùng 学生.'),
('入管', null, 'cơ quan/quản lý xuất nhập cảnh và cư trú (cách gọi tắt)', '入管 là cách gọi tắt trong hội thoại. Khi hướng dẫn thủ tục thực tế cần kiểm tra tên cơ quan và thông tin chính thức hiện hành.'),
('営業', null, 'kinh doanh; bán hàng; hoạt động/mở cửa kinh doanh', '営業部、営業担当、店が営業している. Nghĩa thay đổi theo tổ hợp.'),
('楽しむ', null, 'tận hưởng; thưởng thức; vui với', '旅行を楽しむ = tận hưởng chuyến đi. “Mong chờ” là 楽しみにする.'),
('塾', null, 'lớp/trường học thêm tư nhân; cram school', 'Có thể học bổ trợ hoặc luyện thi; không chỉ luyện thi.'),
('領収書', null, 'biên lai; hóa đơn/receipt xác nhận đã thanh toán', '領収書 = receipt. 請求書 = invoice/yêu cầu thanh toán.'),
('点', null, 'điểm; điểm số; khía cạnh/điểm cần chú ý', '100点, 良い点, 改善すべき点. Không chỉ điểm bài thi.'),
('回答', null, 'câu trả lời; phản hồi; trả lời', '質問／アンケート／問い合わせに回答する.'),
('こちら', null, 'đây; phía này; phía chúng tôi', 'Đại từ lịch sự của ここ／こっち và có thể chỉ phía người nói/công ty mình.'),
('慌てる', null, 'hốt hoảng; cuống; vội vàng trong bối rối', '慌てないでください. Không đơn giản chỉ là “đi vội”.'),
('暗証番号', null, 'mã PIN; mã số bí mật', 'Thường là mã bằng số. “Mật khẩu” nói chung thường パスワード.'),
('宝庫', null, 'kho tàng; nguồn phong phú', 'Nの宝庫 = nơi/nguồn có rất nhiều N hữu ích: 知識の宝庫.'),
('信号', null, 'tín hiệu; đèn/tín hiệu giao thông tùy ngữ cảnh', '信号が青になる = đèn giao thông; 警告信号 = tín hiệu cảnh báo.'),
('梅', null, 'cây/quả/hoa mơ Nhật (ume)', '梅 có thể chỉ cây, quả hoặc hoa tùy câu. Không chỉ “hoa mơ”.'),
('コース', null, 'khóa học; tuyến/lộ trình; course', '研修コース、登山コース、料理のコース. Nghĩa tùy tổ hợp.'),
('スタート', null, 'bắt đầu; khởi đầu; xuất phát', 'プロジェクトがスタートする、レースがスタートする. Không chỉ “xuất phát”.'),
('賞金', null, 'tiền thưởng giải; tiền thưởng cuộc thi', 'コンテストの賞金. Khác ボーナス = thưởng công việc.'),
('係の者', null, 'người/nhân viên phụ trách', 'Trong dịch vụ/điện thoại, 係の者 thường chỉ người phụ trách phía công ty/người nói.'),
('参る', null, 'đi; đến (khiêm nhường ngữ)', '行く／来る の謙譲語: 御社へ参ります.'),
('おっしゃる', null, 'nói (kính ngữ)', '言う の尊敬語: 社長がおっしゃる.'),
('いただく', null, 'nhận; ăn/uống (khiêm nhường ngữ)', 'もらう の謙譲語; 食べる／飲む の khiêm nhường/lịch sự trong nhiều ngữ cảnh.'),
('続ける', null, 'tiếp tục (tha động từ)', '仕事を続ける、勉強を続ける. 続く là tự động từ: 雨が続く.'),
('ごみ収集車', null, 'xe thu gom rác', 'ごみを収集する車.'),
('サッカー選手', null, 'cầu thủ bóng đá', 'サッカーをする選手.'),
('楽しみにしております', null, 'rất mong chờ (cách nói lịch sự)', '楽しみにしています の lịch sự/khiêm nhường hơn; thường dùng trong email/công việc.'),
('お待ちしております', null, 'chúng tôi mong/chờ đón; đang chờ (cách nói rất lịch sự)', 'お待ちしています より丁寧. 接客・案内メールでよく使う.' )
)
update public.jp_vocab v
set meaning_vi = f.meaning_vi,
    usage_note_vi = f.usage_note_vi
from fixes f
where v.level = 'N4'
  and v.word_jp = f.word_jp
  and (f.reading_furigana is null or v.reading_furigana = f.reading_furigana);